static unsigned expanded_month_day60(uint64_t utc){unsigned doe=(unsigned)((utc/86400+719468)%146097),yoe=(doe-doe/1460+doe/36524-doe/146096)/365,doy=doe-(365*yoe+yoe/4-yoe/100),mp=(5*doy+2)/153;return doy-(153*mp+2)/5+1;}
static int stargladiator_day60(unsigned aspect){unsigned day=expanded_month_day60(bossNow53);return aspect==0?day%2==0:aspect==1?day%2==1:day%5==0;}
static int stargladiator_feel60(const Combat*g,unsigned aspect){return aspect<3&&(g->class50.sgMiracleUntil60>g->time||g->expanded60.feelMaps[aspect]==g->mapId+1);}
static int stargladiator_anger60(const Combat*g,const CombatMob*m){for(unsigned i=0;i<3;i++)if(g->class50.sgMiracleUntil60>g->time?i==2:g->expanded60.hateSources[i]==(unsigned)mobSpecs[m->kind].id){int rank=class_rank50(g,SK60_SG_SUN_ANGER+i);if(!rank)return 0;int ratio=g->level+stat_value(g,4)+stat_value(g,5)+(i==2?stat_value(g,0):0);return rank<4?ratio/(12-3*rank):ratio;}return 0;}
static int stargladiator_exp60(const Combat*g,const CombatMob*m){for(unsigned i=0;i<3;i++)if(g->class50.sgMiracleUntil60>g->time?i==2:g->expanded60.hateSources[i]==(unsigned)mobSpecs[m->kind].id&&stargladiator_day60(i))return (i==2?20:10)*class_rank50(g,SK60_SG_SUN_BLESS+i);return 0;}
static void stargladiator_hit60(Combat*g){if(g->jobId==J60_STAR_GLADIATOR&&combat_random(g)%10000<1)g->class50.sgMiracleUntil60=g->time+3600;}
static void expanded_login60(Combat*g){int rank=class_rank50(g,SK60_SG_KNOWLEDGE);if(!rank)return;for(int i=0;i<3;i++)if(g->expanded60.feelMaps[i]==g->mapId+1){g->class50.level[SK60_SG_KNOWLEDGE-127]=rank;g->class50.until[SK60_SG_KNOWLEDGE-127]=g->time+86400;g->class50.sgKnowledgeMap60=g->mapId+1;break;}}
static void expanded_travel60(Combat*g,unsigned targetMap){g->class50.sgMiracleUntil60=0;if(!class_active50(g,SK60_SG_KNOWLEDGE))return;unsigned map=targetMap+1;for(int i=0;i<3;i++)if(g->expanded60.feelMaps[i]==map){g->class50.sgKnowledgeMap60=map;return;}if(g->class50.sgKnowledgeMap60){g->class50.sgKnowledgeMap60=0;g->class50.until[SK60_SG_KNOWLEDGE-127]=g->time+600;}}
